by_ip.map:
function(doc) {
  if (doc.dtype && doc.dtype.toLowerCase() === 'host' && doc.ip) {
    emit(doc.ip, doc._id);
  }
}

by_hostname.map:
function(doc) {
  if (doc.dtype && doc.dtype.toLowerCase() === 'host' && doc.hostname) {
    emit(doc.hostname, doc._id);
  }
}

by_port.map:
function(doc) {
  if (doc.dtype && doc.dtype.toLowerCase() === 'host' && doc.ports && Array.isArray(doc.ports)) {
    for (var i = 0; i < doc.ports.length; i++) {
      if (doc.ports[i].port) {
        emit(doc.ports[i].port, doc._id);
      }
    }
  }
}

